(5026325, 733379, 75585, '<td valign="top">Wildlife photographer for last weeks challenge :-)  LOL</td>', 'Wildlife photographer for last weeks challenge :-)  LOL', '2008-10-27 00:12:02.000000', NULL, 1),
(5026348, 733856, 27133, '<td valign="top">Good work.  I so wanted to be able to capture this man''s photo.  Lucky girl!</td>', 'Good work.  I so wanted to be able to capture this man''s photo.  Lucky girl!', '2008-10-27 00:20:49.000000', NULL, 1),
