(5026448, 733613, 75585, '<td valign="top">I like the guy with his McCain shirt in the background looking at him like he is crazy</td>', 'I like the guy with his McCain shirt in the background looking at him like he is crazy', '2008-10-27 01:32:27.000000', NULL, 1),
(5026449, 733644, 75585, '<td valign="top">Great tones on this - so many photographers :-)</td>', 'Great tones on this - so many photographers :-)', '2008-10-27 01:33:06.000000', NULL, 1),
