(5026463, 733402, 75585, '<td valign="top">I would have liked the use of SC on this if it had just been the guy on the piano or just the child</td>', 'I would have liked the use of SC on this if it had just been the guy on the piano or just the child', '2008-10-27 01:44:05.000000', NULL, 1),
