(5026466, 733340, 75585, '<td valign="top">This would have been great in BW too.  The picture looks a tad overexposed but then again my monitor is super bright so gonna go with my monitor being off :-)</td>', 'This would have been great in BW too.  The picture looks a tad overexposed but then again my monitor is super bright so gonna go with my monitor being off :-)', '2008-10-27 01:45:41.000000', NULL, 1),
(5026467, 732973, 75585, '<td valign="top">Love love love that blue with the orange great color combo!</td>', 'Love love love that blue with the orange great color combo!', '2008-10-27 01:46:19.000000', NULL, 1),
(5026469, 733265, 75585, '<td valign="top">Quite a sad shot - nice job</td>', 'Quite a sad shot - nice job', '2008-10-27 01:47:12.000000', NULL, 1),
