(5026472, 733761, 33672, '<td valign="top">VEry nice line. Needs more contrast though. (IMO)</td>', 'VEry nice line. Needs more contrast though. (IMO)', '2008-10-27 01:47:48.000000', NULL, 1),
(5026481, 733340, 97614, '<td valign="top">Great expression on his face!</td>', 'Great expression on his face!', '2008-10-27 01:55:38.000000', NULL, 1),
(5026485, 733382, 97614, '<td valign="top">I think the picture is a bit to dark.</td>', 'I think the picture is a bit to dark.', '2008-10-27 01:57:30.000000', NULL, 1),
(5026486, 733465, 27133, '<td valign="top">Well set up.  I like the work and thought you put into this. 8</td>', 'Well set up.  I like the work and thought you put into this. 8', '2008-10-27 01:57:38.000000', NULL, 1),
(5026502, 733381, 75585, '<td valign="top">I really like the dog at the restaurant and the man reading alone while everyone mingles (even the dog).</td>', 'I really like the dog at the restaurant and the man reading alone while everyone mingles (even the dog).', '2008-10-27 02:28:39.000000', NULL, 1),
(5026504, 733801, 75585, '<td valign="top">I like this shot - I don''t think it is candid but the color and tones are so edgy and "street smart" my vote is a 9 and I predict a top 5 finish for you on this one.</td>', 'I like this shot - I don''t think it is candid but the color and tones are so edgy and "street smart" my vote is a 9 and I predict a top 5 finish for you on this one.', '2008-10-27 02:28:52.000000', NULL, 1),
(5026524, 733739, 28882, '<td valign="top">this is <b>actual</b> street photography, i''d give you an 8 if i could vote</td>', 'this is actual street photography, i''d give you an 8 if i could vote', '2008-10-27 03:06:42.000000', NULL, 1),
