(5026660, 733803, 31889, '<td valign="top">Nice street scene.  Would''ve preferred if you hadn''t chopped them off at the ankles.</td>', 'Nice street scene.  Would''ve preferred if you hadn''t chopped them off at the ankles.', '2008-10-27 06:45:20.000000', NULL, 1),
