(5027439, 733904, 63398, '<td valign="top">So wrong, and yet, so right! Great find, nicely captured. 7</td>', 'So wrong, and yet, so right! Great find, nicely captured. 7', '2008-10-27 14:40:30.000000', NULL, 1),
