(5027455, 732443, 63398, '<td valign="top">A good rendition of the challenge. Simple, clean, and succinct. 7</td>', 'A good rendition of the challenge. Simple, clean, and succinct. 7', '2008-10-27 14:46:44.000000', NULL, 1),
(5027457, 732866, 4493, '<td valign="top">Took me a second to see the smoke in her hand. Like many images in the challenge if we''d have one of the subjects looking at the camera so we could read the story in her face, it''d make for a stronger shot. A closer crop may have helped make this more engaging and a stronger shot.</td>', 'Took me a second to see the smoke in her hand. Like many images in the challenge if we''d have one of the subjects looking at the camera so we could read the story in her face, it''d make for a stronger shot. A closer crop may have helped make this more engaging and a stronger shot.', '2008-10-27 14:47:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5027458, 733381, 63398, '<td valign="top">Awesome scene! well seen! Niicely done image. 8</td>', 'Awesome scene! well seen! Niicely done image. 8', '2008-10-27 14:47:21.000000', NULL, 1),
(5027459, 732647, 63398, '<td valign="top">I like the processing even if the image looks slightly contrived to me. 7</td>', 'I like the processing even if the image looks slightly contrived to me. 7', '2008-10-27 14:47:48.000000', NULL, 1),
(5027463, 733265, 63398, '<td valign="top">A well-done example.....not to my tastes, but very much meets the challenge well. 7</td>', 'A well-done example.....not to my tastes, but very much meets the challenge well. 7', '2008-10-27 14:48:31.000000', NULL, 1),
(5027464, 733463, 4493, '<td valign="top">Seeing the man''s profile adds a lot to the image. I would bet that a color version would just as strong or stronger than the bw version. The boat and bird add to the shot and allow the eye to move around the image with the log drawing the eye back to the people sitting on it.</td>', 'Seeing the man''s profile adds a lot to the image. I would bet that a color version would just as strong or stronger than the bw version. The boat and bird add to the shot and allow the eye to move around the image with the log drawing the eye back to the people sitting on it.', '2008-10-27 14:48:44.000000', NULL, 1),
(5027466, 733524, 86336, '<td valign="top">excellent pic. good luck.</td>', 'excellent pic. good luck.', '2008-10-27 14:49:50.000000', NULL, 1),
(5027473, 733910, 86336, '<td valign="top">A little bit over expose.  Levels will helps to do the job.</td>', 'A little bit over expose.  Levels will helps to do the job.', '2008-10-27 14:53:15.000000', NULL, 1),
(5027476, 733492, 85451, '<td valign="top">Wow I totally have that shirt. <br/> <br/>I didn''t like this shot at first, seemed boring. I''ve been looking at it for a few minutes and I do find the expression on the mans face interesting. It looks like he''s getting some sort of bad news, or trying to fain interest in what she is saying.</td>', 'Wow I totally have that shirt.  I didn''t like this shot at first, seemed boring. I''ve been looking at it for a few minutes and I do find the expression on the mans face interesting. It looks like he''s getting some sort of bad news, or trying to fain interest in what she is saying.', '2008-10-27 14:56:31.000000', NULL, 1),
(5027478, 733171, 85451, '<td valign="top">Very cool shot, weird angle. Were you driving by in a car or sitting down at a bench when you took it?</td>', 'Very cool shot, weird angle. Were you driving by in a car or sitting down at a bench when you took it?', '2008-10-27 14:57:31.000000', NULL, 1),
(5027481, 732866, 85451, '<td valign="top">I understand smoking a bit of weed, that''s fine and all - but did they really have to litter?! Dastardly!<br/> <br/>I really do like this shot, I''m wondering what a crop right hand side would look like - getting rid of that metalic door, then again maybe it would take away from it?<br/> <br/>The overall dark feeling is quite good.</td>', 'I understand smoking a bit of weed, that''s fine and all - but did they really have to litter?! Dastardly! I really do like this shot, I''m wondering what a crop right hand side would look like - getting rid of that metalic door, then again maybe it would take away from it? The overall dark feeling is quite good.', '2008-10-27 14:59:25.000000', NULL, 1),
(5027483, 733885, 85451, '<td valign="top">doesn''t really convey street photography to me. If you would have maybe left in some of the background elements it would have helped.</td>', 'doesn''t really convey street photography to me. If you would have maybe left in some of the background elements it would have helped.', '2008-10-27 15:00:00.000000', NULL, 1),
(5027485, 733508, 85451, '<td valign="top">I would have scored this a 10 had that big black blob not been on the left hand side.</td>', 'I would have scored this a 10 had that big black blob not been on the left hand side.', '2008-10-27 15:00:40.000000', NULL, 1),
(5027511, 733351, 85451, '<td valign="top">What''s Gerard Butler from 300 doing to that lady in the painting?!  Grea shot, I''m assuming that''s a graffiti removal truck?</td>', 'What''s Gerard Butler from 300 doing to that lady in the painting?!  Grea shot, I''m assuming that''s a graffiti removal truck?', '2008-10-27 15:18:24.000000', NULL, 1),
(5027567, 733695, 4493, '<td valign="top">Aside from the edges of the images pulling my eyes away from your subject, the image is good. Try a tighter crop to remove the rough/dark areas on either side to keep the eye going toward your subject walking down the corridor.</td>', 'Aside from the edges of the images pulling my eyes away from your subject, the image is good. Try a tighter crop to remove the rough/dark areas on either side to keep the eye going toward your subject walking down the corridor.', '2008-10-27 15:59:28.000000', NULL, 1),
(5027570, 733505, 4493, '<td valign="top">I know who took this! I like this shot a lot. Who wouldn''t burn out getting to that bride? The square crop works great for this composition.</td>', 'I know who took this! I like this shot a lot. Who wouldn''t burn out getting to that bride? The square crop works great for this composition.', '2008-10-27 16:00:33.000000', NULL, 1),
(5027571, 733114, 4493, '<td valign="top">The subject I assume is referring to the people on the right. This composition loses them and I focus on the spilled water in the middle. Get closer, adjust your angle, get into the shot so that I can focus on what you want me to... as it is now, I have to many competing elements to find one central focal point.</td>', 'The subject I assume is referring to the people on the right. This composition loses them and I focus on the spilled water in the middle. Get closer, adjust your angle, get into the shot so that I can focus on what you want me to... as it is now, I have to many competing elements to find one central focal point.', '2008-10-27 16:02:08.000000', NULL, 1),
(5027576, 733767, 4493, '<td valign="top">Drive by shooting? There is motion blur that leads me to believe this. Did you get out, talk to the men, explain your project and ask if you could hang out and take some pictures? I think if you had you''d have engaged them and gotten an image that draws the viewer in more and feel more for what they''re there for. As it is, the guy on the phone doesn''t make me feel for their cause. Tone, exposure, and post processing are good for this type shot.</td>', 'Drive by shooting? There is motion blur that leads me to believe this. Did you get out, talk to the men, explain your project and ask if you could hang out and take some pictures? I think if you had you''d have engaged them and gotten an image that draws the viewer in more and feel more for what they''re there for. As it is, the guy on the phone doesn''t make me feel for their cause. Tone, exposure, and post processing are good for this type shot.', '2008-10-27 16:07:59.000000', NULL, 1),
(5027588, 733402, 96653, '<td valign="top">Captured the kids look perfectly.  Really tells a story.  Great picture.</td>', 'Captured the kids look perfectly.  Really tells a story.  Great picture.', '2008-10-27 16:13:29.000000', NULL, 1),
(5027591, 733298, 96653, '<td valign="top">Great colors...  tells a story for sure.</td>', 'Great colors...  tells a story for sure.', '2008-10-27 16:15:21.000000', NULL, 1),
(5027592, 733226, 6667, '<td valign="top">The Cleveland sax man.  What event were you at?</td>', 'The Cleveland sax man.  What event were you at?', '2008-10-27 16:16:06.000000', NULL, 1),
(5027602, 733561, 58728, '<td valign="top">WOW.  Really cool.  Amazing composition and processing.  LOVE it.  10 and a fave from me.  :)</td>', 'WOW.  Really cool.  Amazing composition and processing.  LOVE it.  10 and a fave from me.  :)', '2008-10-27 16:22:06.000000', NULL, 1),
(5027610, 733363, 58728, '<td valign="top">I keep coming back to this image - The little kitten''s expression just reiterates the sadness of the whole picture.  This is perfect. 10 and a fave.</td>', 'I keep coming back to this image - The little kitten''s expression just reiterates the sadness of the whole picture.  This is perfect. 10 and a fave.', '2008-10-27 16:28:06.000000', NULL, 1),
(5027625, 733738, 49804, '<td valign="top">Whoa i may be off, but is this right near Windsor Castle. Sorry, i just got back from there, interesting shot, nice capture of him in action, I''d like to be able to see his face (a bit brighter, nonetheless, a nice "street" shot.</td>', 'Whoa i may be off, but is this right near Windsor Castle. Sorry, i just got back from there, interesting shot, nice capture of him in action, I''d like to be able to see his face (a bit brighter, nonetheless, a nice "street" shot.', '2008-10-27 16:34:25.000000', NULL, 1),
(5027635, 733062, 49804, '<td valign="top">Very cool, great tones here, lovely colors, very well done, 8</td>', 'Very cool, great tones here, lovely colors, very well done, 8', '2008-10-27 16:38:27.000000', NULL, 1),
(5027643, 733444, 49804, '<td valign="top">6- I''d like a tighter crop in on the subject, the rest of the guys i find rather distracting, I do like the stopped motion however hear, and a added feel of emotion from that.</td>', '6- I''d like a tighter crop in on the subject, the rest of the guys i find rather distracting, I do like the stopped motion however hear, and a added feel of emotion from that.', '2008-10-27 16:40:15.000000', NULL, 1),
