(5027656, 733149, 49804, '<td valign="top">Very cool tones, really cool shot as well, i would prefer to see the woman on the right hand side walking to balance the shot better, but what can you do its candid, very cool shot and an 8 from me.</td>', 'Very cool tones, really cool shot as well, i would prefer to see the woman on the right hand side walking to balance the shot better, but what can you do its candid, very cool shot and an 8 from me.', '2008-10-27 16:43:11.000000', NULL, 1),
(5027662, 733561, 49804, '<td valign="top">Great shot, love the motion going on here, very nicely done, looks almost like a lens baby was used. very cool effect, nice pp as well, 8</td>', 'Great shot, love the motion going on here, very nicely done, looks almost like a lens baby was used. very cool effect, nice pp as well, 8', '2008-10-27 16:45:21.000000', NULL, 1),
(5027666, 733739, 49804, '<td valign="top">This is kind of wild, saw a similar shot previously in the challenge, i imagine this was shot together, love this shot as well, very nice tones, like the vertical crop here, 8 from me.</td>', 'This is kind of wild, saw a similar shot previously in the challenge, i imagine this was shot together, love this shot as well, very nice tones, like the vertical crop here, 8 from me.', '2008-10-27 16:46:53.000000', NULL, 1),
