(5027690, 733330, 49804, '<td valign="top">Whoa dang, this is absolutely phenomenal, my only 10 in the challenge, love the symmetry, very nicely done, great job here.</td>', 'Whoa dang, this is absolutely phenomenal, my only 10 in the challenge, love the symmetry, very nicely done, great job here.', '2008-10-27 16:56:16.000000', NULL, 1),
