(5028588, 733767, 94239, '<td valign="top">I think you tried to focus in on the sign, but overall this just seems a bit too out of focus to me, overall. But a good composition.</td>', 'I think you tried to focus in on the sign, but overall this just seems a bit too out of focus to me, overall. But a good composition.', '2008-10-28 07:29:25.000000', NULL, 1),
(5028589, 732866, 95579, '<td valign="top">Cant say much about this apart from I love it. Really gives a sense of sadness that life can be like that.  Nicely framed in the doorway, contrast and shadows is very moody - 9</td>', 'Cant say much about this apart from I love it. Really gives a sense of sadness that life can be like that.  Nicely framed in the doorway, contrast and shadows is very moody - 9', '2008-10-28 07:30:32.000000', NULL, 1),
(5028591, 733907, 95579, '<td valign="top">I want to be there dancing too!!  Love the shot - 9</td>', 'I want to be there dancing too!!  Love the shot - 9', '2008-10-28 07:31:10.000000', NULL, 1),
(5028592, 733571, 94239, '<td valign="top">Very nice sharp image, and good b&amp;w. Interesting capture andgood  compostion.</td>', 'Very nice sharp image, and good b&w. Interesting capture andgood  compostion.', '2008-10-28 07:31:36.000000', NULL, 1),
