(5028618, 733402, 94239, '<td valign="top">Good capture of a candid moment. In some ways I like the way you have processed this, but I also think it could be a bit overstated for what is a poignant moment. Maybe more subtlety would have been better, for me.</td>', 'Good capture of a candid moment. In some ways I like the way you have processed this, but I also think it could be a bit overstated for what is a poignant moment. Maybe more subtlety would have been better, for me.', '2008-10-28 08:08:57.000000', NULL, 1),
(5028620, 733381, 94239, '<td valign="top">Beautiful image. So many stories in what seems almost like 2 separate pictures, with the light and dark.</td>', 'Beautiful image. So many stories in what seems almost like 2 separate pictures, with the light and dark.', '2008-10-28 08:12:13.000000', NULL, 1),
(5028626, 733298, 94239, '<td valign="top">Nice to see some beautiful colour after so much black and white. Very strong image, great composition. I think the oversharpnening? lets it down a bit.</td>', 'Nice to see some beautiful colour after so much black and white. Very strong image, great composition. I think the oversharpnening? lets it down a bit.', '2008-10-28 08:15:18.000000', NULL, 1),
