(5033573, 732863, 26464, '<td valign="top">trippy</td>', 'trippy', '2008-10-30 19:39:23.000000', NULL, 1),
(5033803, 733705, 4493, '<td valign="top">Average random shot with over post processing to try and make more out of a shot that doesn''t have flow through the image or a subject matter that will hold the viewers interest (even though she''s kind of cute)</td>', 'Average random shot with over post processing to try and make more out of a shot that doesn''t have flow through the image or a subject matter that will hold the viewers interest (even though she''s kind of cute)', '2008-10-30 23:54:09.000000', NULL, 1),
(5033806, 733402, 4493, '<td valign="top">I can see what you were going for with the selective desaturation, but I don''t feel it''s necessary. Being that the kid clearly has a fix on the man with the keyboard I think the viewer would have picked up on that without the post processing as it is. Either color or black and white, but the mix doesn''t work for me.</td>', 'I can see what you were going for with the selective desaturation, but I don''t feel it''s necessary. Being that the kid clearly has a fix on the man with the keyboard I think the viewer would have picked up on that without the post processing as it is. Either color or black and white, but the mix doesn''t work for me.', '2008-10-30 23:55:58.000000', NULL, 1),
(5033811, 733572, 4493, '<td valign="top">Tone and capture of the man is good. I would like to see a crop that is less of the left and top of the frame. All the added distraction on those areas pulls my interest from the man with the headphones.</td>', 'Tone and capture of the man is good. I would like to see a crop that is less of the left and top of the frame. All the added distraction on those areas pulls my interest from the man with the headphones.', '2008-10-30 23:57:49.000000', NULL, 1),
(5033903, 733761, 16929, '<td valign="top">I dont know what it is.. I love this shot.</td>', 'I dont know what it is.. I love this shot.', '2008-10-31 02:24:36.000000', NULL, 1),
