(5038194, 733775, 7810, '<td valign="top">This is an interesting shot. I am glad you left the colour in ... I love the blues between the umbrella and the wall  I also love the turned up section of the umbrella ... good work here</td>', 'This is an interesting shot. I am glad you left the colour in ... I love the blues between the umbrella and the wall  I also love the turned up section of the umbrella ... good work here', '2008-11-02 08:58:45.000000', NULL, 1),
(5038195, 733715, 7810, '<td valign="top">Love it  ... nice capture ... great composition  love the rain</td>', 'Love it  ... nice capture ... great composition  love the rain', '2008-11-02 08:58:48.000000', NULL, 1),
(5038196, 733515, 7810, '<td valign="top">The spectators make this shot great pic well captured</td>', 'The spectators make this shot great pic well captured', '2008-11-02 08:58:50.000000', NULL, 1),
