(5038201, 733708, 7810, '<td valign="top">Good take for the challenge ... composition good interesting backdrop ... well done</td>', 'Good take for the challenge ... composition good interesting backdrop ... well done', '2008-11-02 08:59:00.000000', NULL, 1),
